pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(
            1,
            100,
            2000000000,
            0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef,
            5,
            0xabcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890,
            1000,
            2000
        );
        assertTrue(c.timestamp() == 100);
    }
}
